INSERT INTO `hesk_notes` (`id`, `ticket`, `who`, `dt`, `message`, `attachments`) VALUES
(1, 463, 9, '2023-02-14 11:54:58', 'LLAMAR ANTES!', ''),
(5, 930, 11, '2023-03-14 22:20:45', 'Esta nota es de prueba, no se muestra al cliente', ''),
(4, 639, 11, '2023-02-24 16:31:56', 'Mensaje de prueba para no mostrar a cliente', ''),
(6, 948, 11, '2023-03-15 14:54:21', 'La cliente me trato mal', ''),
(7, 968, 11, '2023-03-16 13:33:55', 'Corrección teléfono : 3544460373<br />\r\n<br />\r\nMe comenta que estuvo en línea varios minutos intentando comunicarse con el area comercial, sin exito.', ''),
(8, 942, 11, '2023-03-16 20:22:27', '16/03  Reitera reclamo, le informaron que los técnicos irían esta mañana, pide que se comuniquen para coordinar. MA', ''),
(9, 975, 11, '2023-03-16 21:04:30', 'El cliente corto antes de poder pedir el dni del titular.', ''),
(10, 981, 11, '2023-03-16 22:51:53', 'Informa que se comuniquen asi les explica donde vive ya que antes se han confundido el domicilio. No me supo aclarar el barrio ya que esta entre dos barrios.', ''),
(11, 838, 11, '2023-03-17 13:56:26', 'Se comunica la clienta porque se excedió el plazo acordado de instalación, solicita si se puede comunicar para coordinar esta.<br />\r\nTel: 3544648013', ''),
(12, 942, 11, '2023-03-17 15:32:45', 'El cliente se comunica muy molesto, esta desde las 8am esperando a los tecnicos y solicita que se comuniquen con el. TEL: 3544468209. LG', ''),
(13, 1085, 11, '2023-03-22 21:24:05', 'COMENTA CLIENTE QUE DESDE ESTA MAÑANA HABIA UN TECNICO EN EL POSTE Y DESPUES DE ESO SE QUEDO SIN INTERNET.', ''),
(14, 1110, 11, '2023-03-24 12:42:36', 'tel: 543923 nuevo telefono', ''),
(15, 1115, 11, '2023-03-24 15:21:46', 'luego del reinicio del poe, retoma correctamente figura online. PPA', ''),
(16, 1115, 11, '2023-03-24 15:24:08', 'levanta el equipo figura online, pero figura radio off en sistema sigue sin tener servicio. PPA', ''),
(17, 1164, 11, '2023-03-27 14:31:17', 'CLIENTE SOLICITA UNA IP FIJA COMO TENIA ANTES PORQUE EL TECNICO QUE TIENEN ELLOS NO PUEDE ENTRAR A LOS SERVIDORES POR ESTE MOTIVO.', ''),
(18, 1168, 11, '2023-03-27 14:49:46', 'CLIENTE DICE QUE HACE TRES MESES QUE TIENE PROBLEMAS CON EL SERVICIO, DICE QUE TIENE LENTITUD POR LA NOCHE CUANDO LO USAN, DICE QUE FUE TRES VECES A LA OFICINAS QUE LE CARGARON UN RECLAMO QUE IBAN A IR Y NO FUERON NUNCA, LE DIJERON QUE LA ENTENA SE HABIA MOVIDO POR EL VIENTO. PIDE QUE SE COMUNIQUEN DESPUES DE LAS 15HS, (NO SE ENCUENTRA EN EL DOMICILIO PARA HACER PRUEBAS)', ''),
(19, 1152, 11, '2023-03-27 21:01:08', 'nuevamente se comunica la cliente muy enojada ya que no ha tenido novedades, informa que si no la llaman el dia de hoy mañana llevara a cabo el pedido de baja en oficina, PPA', ''),
(20, 1133, 11, '2023-03-28 21:12:12', 'Se comunica nuevamente, le informaron que el técnico iría el día de hoy en el horario de las 17hs y lo está esperando, pide por favor se comuniquen y vayan el día de hoy ya que tiene franco, otro día se le complica para estar en su domicilio. MA', ''),
(21, 1048, 11, '2023-03-28 21:36:35', 'SE COMUNICA CLIENTE SOLICITA, QUE LE DEN ATENCION A SU RECLAMO,  YA SE VENCIORON LOS PLAZOS, NO SE PUEDE CONECTAR A LA RED 2.4ghz , NECESITA QUE LE PONGAN ESA CONTRASEÑA Y QUE LE AVISEN CUANDO ESTE HECHO.', ''),
(22, 1059, 11, '2023-03-28 21:38:42', 'SE COMUNICA CLIENTE , ESTA VENCIDO EL RECLAMO Y NO TIENE SOLUCION AUN. HAY DOS RECLAMOS ABIERTOS VENCIDOS.', ''),
(23, 1249, 11, '2023-03-29 21:42:41', 'cliente se comunico por wsp el jueves pasado, los tecnicos fueron el lunes a su domucilio y no le pudieron resolver el problema comenta el cliente, dice que le dijeron que iban a volver al otro dia y no volvieron mas. Esta muy enojado.', ''),
(24, 1027, 11, '2023-03-29 22:47:16', 'cliente se comunica porque no pudo atender los llamados, tenia en volumen bajo, tel 3544589526,  dice que mañana a la mañana esta disponible para la instalacion.', ''),
(25, 1260, 11, '2023-03-29 23:16:07', 'hicimos reinicio de poe y router manualmente y medimos con fast.com y los valores fueron desarga 2.7mb ,      latencia descargada 91ms   cargada 460ms  velocidad de carga 640kbps', ''),
(26, 1274, 11, '2023-03-30 21:14:55', 'no pude rellenar bien los campos del ticket porque justo se corto la llamada y no llamo mas el cliente, habia llamado anteriormente a administracion dice y lo derivaron a soporte tecnico.', ''),
(27, 1274, 11, '2023-03-30 21:19:15', 'los campos rellenados son cualquier numero, es para que me cargara el ticket nomas, aclaro.', ''),
(28, 1298, 11, '2023-04-03 12:31:51', 'En todos los dispositivos. SG', ''),
(29, 1305, 11, '2023-04-03 14:28:36', 'le dijeron que iban a ir otros tecnicos el sabado pero no fue nadie, dice que los tecnicos estan al tanto del problema, y se comunico hoy nuevamente para saber cuando van a volver.', ''),
(30, 1069, 11, '2023-04-05 14:40:44', 'Se comunica para saber cuándo se realizará la conexión ya que el electricista ya fue, pide que se comuniquen así coordinan con el electricista. MA', ''),
(31, 1382, 11, '2023-04-06 14:15:59', 'luego de ambos reinicios retoma de manera correcta el servicio. PPA', ''),
(32, 1430, 11, '2023-04-11 15:31:51', 'Se vuelve a comunicar, solicita que se communiquen con ella para coordinar horario de visita ya que trabaja y no puede esperar en su domicilio a los tecnicos. LA', ''),
(33, 1520, 11, '2023-04-17 14:26:27', '17/04 Reitera reclamo. De muy mala manera insiste en que necesita un cambio de router. MA', ''),
(34, 1577, 11, '2023-04-20 14:48:37', 'La clienta asegura que el dia de ayer le dijeron que irían hoy los técnicos ya que realizo el pedido por WhatsApp', ''),
(35, 752, 11, '2023-04-25 14:30:30', 'Se comunica la clienta avisando que estará en su domicilio hasta las 15:30. Luego no podrá recibir técnicos', ''),
(36, 1637, 4, '2023-04-25 19:28:42', 'se comunico mauro. les informa que estan teniendo problemas con el router. quedan en buscar uno para cambiarlo', ''),
(38, 1752, 4, '2023-05-04 18:59:23', '15:59 chequea cliente onlline hace 3 hrs.', ''),
(39, 2014, 11, '2023-05-31 13:55:02', 'Se comunica la clienta reiterando el pedido. Comenta que le esta sucediendo en otro televisor mas en el domicilio.', ''),
(40, 2024, 11, '2023-05-31 14:34:20', 'No se dejo asentado el mail ya que no recuerda ni el suyo ni el de su marido', ''),
(41, 2069, 4, '2023-06-05 17:56:33', 'se reinicio antena con señal alta enlazada a PAPbar, se conecta a panel M 18, queda en -62. prueba de velocidad down 47 up 7', ''),
(42, 2206, 11, '2023-06-15 13:50:14', 'Si la visita es hoy o mañana debe ser si o si por la mañana', ''),
(43, 2222, 11, '2023-06-16 14:13:39', 'Cliente llama y dice que hace rato que intenta comunicarse con administracion y no le contesta nadie, quiere trasladar el servicio a la casa que esta adelante de donde esta. Porque se muda ahi, solicta que se pongan en contacto cuando antes para hacer el traslado.', ''),
(44, 1493, 4, '2023-06-22 11:07:14', '8:05 cliente con servicio funcionando hace 11hrs, conectado  M14', ''),
(45, 2269, 11, '2023-06-22 14:36:04', 'Quiero aclarar que no fue posible realizar chequeos ya que no se encontraba en su domicilio. El cliente me comento que realizo reinicios', ''),
(46, 2280, 11, '2023-06-23 13:32:20', 'LO NECESITA URGENTE PARA TRABAJAR EL CLIENTE, LE DIJERON AYER EN LA OFICINA QUE LE CARGARON EL RECLAMO Y NO ESTABA CARGADO.', ''),
(47, 2319, 11, '2023-06-27 14:15:50', 'No había nadie en su casa y no quería llamar después porque le fue muy difícil comunicarse, por esta razón no fue posible realizar ninguna prueba', ''),
(48, 2363, 11, '2023-06-30 15:28:53', 'SE HACE REINICIO DE POE Y ROUTER Y PRUEBA EN LA COMPU Y LE FUNCIONA LENTO, DICE QUE HACE TODO EL AÑO QUE ESTA ASI, DICE QUE NECESITA QUE VAYA UN TECNICO A VER QUE PASA', ''),
(49, 1737, 4, '2023-07-03 11:37:58', '08-36.. se reinicia equipo cliente,, queda conectado a panel M18.. señal -44. us: sdemarchi.', ''),
(50, 2377, 4, '2023-07-03 13:28:49', '10:25, verifica cliente online hace 40 minutos, link test 60 x 18', ''),
(51, 2492, 11, '2023-07-10 15:04:49', 'Dice la cliente que la semana pasada le paso lo mismo y cambiaron el cable, ahora vuelve a tener el mismo problema al parecer.', ''),
(52, 2492, 11, '2023-07-10 15:06:26', 'Pide que la llamen primero al telefono de contacto, antes de hacer la visita.<br />\r\nMB', ''),
(53, 816, 4, '2023-07-10 19:21:31', 'se volvio a colocar antena sobre el tanque de casa, se conecta a m 14, nivel de señal -70', ''),
(54, 2487, 4, '2023-07-12 11:58:50', 'baja realiizada por marcos el dia 11-7-23. por la tarde, cliente entrega equipo', ''),
(55, 2421, 11, '2023-07-13 15:02:41', 'Cliente llama informando que tenia asistencia a las 09:00, avisa que se encuentra en el domicilio hasta las 13 hs. En caso de que asistan despues de esa hora que se comuniquen para poder dejar a alguien mayor de 18 años para recibirlos. SG', ''),
(56, 2572, 11, '2023-07-14 16:07:16', 'Cliente agrega que hoy a la mañana la asistieron SG', ''),
(57, 2589, 11, '2023-07-17 15:08:11', 'SG', ''),


